import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.find.js";
import "core-js/modules/es.iterator.some.js";
// Imports
import AssetHandover from "@/components/Asset/Popups/AssetHandover.vue";
import AssetTransfer from "@/components/Asset/Popups/AssetTransfer.vue";
import UserAssetdetails from "@/components/Asset/Popups/UserAssetdetails.vue";
import UserRequestAsset from "@/components/Asset/Popups/UserRequestAsset.vue";
import SnackBar from "@/components/SnackBar.vue";
import { API, graphqlOperation } from "aws-amplify";
import { list_user_assets } from "@/graphql/queries.js";
export default {
  props: {
    searchValue: {
      type: String,
      default: ""
    }
  },
  // Components
  components: {
    SnackBar,
    UserAssetdetails,
    AssetTransfer,
    AssetHandover,
    UserRequestAsset
  },
  // Data
  data() {
    return {
      // Array properties
      adminassetHeaders: [{
        title: "Asset ID",
        key: "asset_prefix",
        sortable: false
      }, {
        title: "Category",
        key: "category_id_text",
        sortable: false
      }, {
        title: "Sub Category",
        key: "sub_category_id_text",
        sortable: false
      }, {
        title: "Product Serial No",
        key: "asset_product_serial_no",
        sortable: false
      }, {
        title: "Last Assigned To",
        key: "last_assigned_to",
        sortable: false
      }, {
        title: "Location",
        key: "asset_location",
        sortable: false
      }, {
        title: "Value",
        key: "asset_value",
        sortable: false
      }, {
        title: "QR Tagged",
        key: "asset_tagged_status",
        sortable: false
      }, {
        title: "Actions",
        key: "actions",
        sortable: false
      }],
      adminassetRecords: [],
      // Object properties
      SnackBarComponent: {},
      assetitems: {},
      // String properties

      // Boolean properties
      tableLoading: false,
      assetdisplay: false,
      transferingasset: false,
      handoveringasset: false,
      requestDialog: true,
      fixed: true,
      adminAppExists: false,
      // Number properties
      componentCheck: 0,
      currentPage: 1,
      itemsPerPage: 20,
      height: 0,
      windowHeight: 0
    };
  },
  // Lifecycle hooks
  async created() {
    this.windowHeight = window.innerHeight - 220;
    this.fetch_admin_apps();
    await this.fetch_userassert();
    this.height = window.innerHeight - 170;
  },
  // Computed properties
  computed: {
    filteredItems() {
      const query = this.searchValue?.toLowerCase().trim();
      if (!query) return this.adminassetRecords;
      return this.adminassetRecords.filter(asset => [asset.asset_prefix, asset.category_id_text, asset.sub_category_id_text, asset.asset_location, asset.asset_product_serial_no, asset.last_assigned_to, asset.asset_value].filter(Boolean).some(val => String(val).toLowerCase().includes(query)));
    },
    totalCount() {
      return this.filteredItems.length;
    },
    startItem() {
      return (this.currentPage - 1) * this.itemsPerPage + 1;
    },
    endItem() {
      return Math.min(this.currentPage * this.itemsPerPage, this.totalCount);
    },
    pageCount() {
      return Math.ceil(this.filteredItems.length / this.itemsPerPage);
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.filteredItems.slice(start, end);
    },
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  // Watchers
  watch: {
    searchValue() {
      this.currentPage = 1;
    },
    currentPage() {
      // Scroll to top when page changes
      const table = document.querySelector(".modern-data-table");
      if (table) table.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    }
  },
  // Methods
  methods: {
    // Admin methods
    fetch_admin_apps() {
      const userObj = this.$store.getters.GetUserObj;

      // Check if userObj and admin_apps exist
      if (!userObj || !userObj.admin_apps || !Array.isArray(userObj.admin_apps)) {
        this.adminAppExists = false;
        return;
      }
      const adminExists = userObj.admin_apps.find(app => app.dashboard_unique_type === "ASSETS_ADMIN");
      if (adminExists.is_visible == false) {
        this.adminAppExists = false;
        return;
      }
      this.adminAppExists = adminExists && (adminExists.app_usage_level === "WEB_PHONE_ONLY" || adminExists.app_usage_level === "WEB_ONLY") && adminExists.is_dashboard_admin === true;
    },
    open_settings() {
      this.$router.push("/home/AssetTypes");
    },
    // Data fetching methods
    async fetch_userassert() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_user_assets, {
          input: {
            user_email_id: data.user.user_email_id
          }
        }));
        var response = JSON.parse(result.data.list_user_assets);
        this.adminassetRecords = [];
        this.tableLoading = false;
        if (response.Status == "SUCCESS") {
          this.adminassetRecords = response.data;
          this.tableLoading = false;
        } else {
          this.adminassetRecords = [];
          this.tableLoading = false;
        }
      } catch (error) {
        this.adminassetRecords = [];
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    // UI interaction methods
    request_asset() {
      this.componentCheck = 4;
      this.requestDialog = true;
    },
    back_call() {
      this.$router.push({
        name: "UserlevelApp"
      });
    },
    open_forwardDailog(item) {
      this.assetitems = item;
      this.componentCheck = 2;
      this.transferingasset = true;
    },
    open_handoverDailog(item) {
      this.assetitems = item;
      this.componentCheck = 3;
      this.handoveringasset = true;
    },
    open_qrDailog(item) {
      // Implement QR dialog functionality
    },
    handle_row_click(click, row) {
      this.assetitems = row;
      this.componentCheck = 1;
      this.assetdisplay = true;
    },
    // Utility methods
    get_date(val) {
      const d = new Date(parseInt(val));
      var date = d.getDate().toLocaleString();
      var month = (d.getMonth() + 1).toLocaleString();
      var year = d.getFullYear();
      return (+date <= 9 ? "0" + date : date) + "/" + (+month <= 9 ? "0" + month : month) + "/" + year;
    },
    // Notification methods
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.transferingasset = false;
      this.handoveringasset = false;
      this.fetch_userassert();
    },
    succces_data(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.requestDialog = false;
    }
  }
};
